#[tokio::test]
async fn molerat_ssrf_blocks_loopback_by_default() {
    let fixture = include_bytes!("fixtures/molerat/index.molerat");
    let (listener, port) = bind().await;
    let acc = acceptor(&self_signed());
    let _server = tokio::spawn(async move { serve_n(listener, acc, fixture, 1).await });

    let adapter = MoleratAdapter::new();
    let policy = FetchPolicy::default(); // block_private_network = true
    let c = ctx(&policy);
    let url = Url::parse(&format!("molerat://localhost:{port}/")).unwrap();

    let err = adapter.fetch(&url, &c).await.unwrap_err();
    assert_eq!(err.code(), "SSRF_BLOCKED");
}

#[tokio::test]
async fn changed_cert_returns_tofu_cert_changed() {
    let fixture = include_bytes!("fixtures/molerat/index.molerat");
    let (listener, port) = bind().await;
    let acc1 = acceptor(&self_signed());
    let acc2 = acceptor(&self_signed());
    let server = tokio::spawn(async move {
        let (tcp, _) = listener.accept().await.unwrap();
        let mut tls = acc1.accept(tcp).await.unwrap();
        let mut buf = [0u8; 1024];
        let n = tls.read(&mut buf).await.unwrap();
        assert_spec_request(&buf[..n]);
        tls.write_all(fixture).await.unwrap();
        tls.shutdown().await.unwrap();

        // Connection 2: client rejects the changed cert and aborts.
        let (tcp, _) = listener.accept().await.unwrap();
        let _ = acc2.accept(tcp).await;
    });

    let adapter = MoleratAdapter::new();
    let policy = local_policy();
    let c = ctx(&policy);
    let url = Url::parse(&format!("molerat://localhost:{port}/")).unwrap();

    // First fetch pins cert1.
    let doc1 = adapter.fetch(&url, &c).await.unwrap();
    assert_eq!(doc1.title.as_deref(), Some("Welcome"));

    // Second fetch sees cert2 — must fail with TofuCertChanged.
    let err = adapter.fetch(&url, &c).await.unwrap_err();
    assert_eq!(err.code(), "TOFU_CERT_CHANGED");
    server.await.unwrap();
}
